def parse_instructions(instructions):
    valid_ops = {"mov", "inc", "dec"}
    result = []

    for instr in instructions:
        parts = instr.split()
        if len(parts) != 3:
            continue

        op, reg, val = parts

        if op not in valid_ops:
            continue

        if not reg.isalpha() or len(reg) != 1:
            continue

        try:
            int(val)
        except ValueError:
            continue

        result.append((op, reg, val))

    return result
