def parse_number_ranges(input_string):
    if not input_string or not input_string.strip():
        return []

    result = []
    parts = input_string.split(',')

    for part in parts:
        part = part.strip()
        if not part:
            continue

        if '-' in part:
            try:
                start_str, end_str = part.split('-', 1)
                start = int(start_str.strip())
                end = int(end_str.strip())

                if start <= end:
                    result.extend(range(start, end + 1))
                else:
                    result.extend(range(start, end - 1, -1))
            except ValueError:
                continue
        else:
            try:
                num = int(part)
                result.append(num)
            except ValueError:
                continue

    return result
