def fibonacci_sequence(n, memo={}):
    if n < 1:
        return []

    def fib(k):
        if k in memo:
            return memo[k]
        if k == 0:
            memo[k] = 0
        elif k == 1:
            memo[k] = 1
        else:
            memo[k] = fib(k - 1) + fib(k - 2)
        return memo[k]

    result = []
    for i in range(n):
        result.append(fib(i))
    return result
