def solve_n_queens(n):
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 'Q':
                return False

        # Check upper diagonal on left side
        i, j = row, col
        while i >= 0 and j >= 0:
            if board[i][j] == 'Q':
                return False
            i -= 1
            j -= 1

        # Check lower diagonal on left side
        i, j = row, col
        while i < n and j >= 0:
            if board[i][j] == 'Q':
                return False
            i += 1
            j -= 1

        return True

    def backtrack(col):
        if col == n:
            return True

        for row in range(n):
            if is_safe(board, row, col):
                board[row][col] = 'Q'
                if backtrack(col + 1):
                    return True
                board[row][col] = '.'  # backtrack

        return False

    board = [['.' for _ in range(n)] for _ in range(n)]
    if backtrack(0):
        for row in board:
            print(" ".join(row))
    else:
        print("Solution does not exist")
