def generate_sequence(start: int, end: int, exceptions: list) -> list:
    if start > end:
        return []

    # Sort exceptions to enable binary search: O(m log m)
    sorted_exceptions = sorted(exceptions)

    result = []
    left, right = 0, len(sorted_exceptions) - 1

    for num in range(start, end + 1):
        # Binary search to check if num is in exceptions: O(log m)
        idx = left
        while left <= right:
            mid = (left + right) // 2
            if sorted_exceptions[mid] == num:
                idx = mid
                break
            elif sorted_exceptions[mid] < num:
                left = mid + 1
            else:
                right = mid - 1

        if idx != left or sorted_exceptions[idx] == num:
            # Found in exceptions; skip
            continue

        result.append(num)

    return result
```

