def get_nth_digit(num, n):
    # Attempt to convert inputs to positive integers
    try:
        num_int = int(num)
        n_int = int(n)
    except (TypeError, ValueError):
        return None

    # Check if they are positive integers (greater than 0)
    if num_int <= 0 or n_int <= 0:
        return None

    # Convert number to string to handle negative numbers correctly (ignore sign)
    num_str = str(abs(num_int))

    # Check if n is greater than the number of digits
    if n_int > len(num_str):
        return 0

    # Get the nth digit from the right (1-based index)
    # Rightmost is index -1, so nth from right is index -(n)
    return int(num_str[-n_int])
```

