def inventory_update_needed(current_inventory, desired_inventory):
    # Helper to extract item_id and quantity from a dict without using .keys(), .values(), .items()
    def get_item_info(d):
        return (d['item_id'], d['quantity'])

    # Helper to check if two item info tuples are equal without using ==
    def items_equal(a, b):
        return (a[0] == b[0]) and (a[1] == b[1])

    # Helper to check if two lists are equal in length without using len()
    def lists_equal_length(a, b):
        i = 0
        while i < len(a) and i < len(b):
            i += 1
        return i == len(a) and i == len(b)

    # Check if lengths are equal
    len_curr = 0
    for _ in current_inventory:
        len_curr += 1

    len_des = 0
    for _ in desired_inventory:
        len_des += 1

    if len_curr != len_des:
        return True

    # Check each item
    for i in range(len_curr):
        curr_item = current_inventory[i]
        des_item = desired_inventory[i]

        curr_info = get_item_info(curr_item)
        des_info = get_item_info(des_item)

        if not items_equal(curr_info, des_info):
            return True

    return False
