def max_depth(tree, node=0):
    if node is None or node not in tree:
        return 0

    left_child, right_child = tree[node]

    left_depth = max_depth(tree, left_child) if left_child is not None else 0
    right_depth = max_depth(tree, right_child) if right_child is not None else 0

    return 1 + max(left_depth, right_depth)
