def roman_to_integer(roman):
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000,
        'i': 1, 'v': 5, 'x': 10, 'l': 50,
        'c': 100, 'd': 500, 'm': 1000
    }

    total = 0
    n = len(roman)

    for i in range(n):
        value = roman_map[roman[i]]
        # If this value is less than the next one, subtract it (subtractive notation)
        if i + 1 < n and value < roman_map[roman[i + 1]]:
            total -= value
        else:
            total += value

    return total
```

