def zip_with_padding(*args):
    # Check that all arguments are iterable and can be converted to tuples
    for arg in args:
        try:
            tuple(arg)
        except TypeError:
            raise TypeError("All arguments must be iterables that can be converted into tuples")

    # Determine the maximum length among all iterables
    max_len = 0
    for arg in args:
        max_len = max(max_len, len(arg))

    # Pad shorter iterables with None and zip them together
    result = []
    for i in range(max_len):
        padded_tuple = tuple(
            arg[i] if i < len(arg) else None
            for arg in args
        )
        result.append(padded_tuple)

    return result
