def sort_by_value(input_dict):
    # Convert dictionary to a list of (key, value) tuples
    items = []
    for k, v in input_dict.items():
        items.append((k, v))

    # Implement a simple selection sort to sort by value in descending order
    n = len(items)
    for i in range(n - 1):
        # Assume the current position holds the maximum value
        max_idx = i
        for j in range(i + 1, n):
            if items[j][1] > items[max_idx][1]:
                max_idx = j
        # Swap the found maximum element with the first element of the unsorted section
        items[i], items[max_idx] = items[max_idx], items[i]

    # Reconstruct the dictionary from the sorted list of tuples
    sorted_dict = {}
    for k, v in items:
        sorted_dict[k] = v

    return sorted_dict
```

