def palindrome_anagram_checker(s1, s2):
    def normalize(s):
        return ''.join(ch for ch in s if ch.isalpha())

    s1_norm = normalize(s1)
    s2_norm = normalize(s2)

    # Check if they are anagrams
    if sorted(s1_norm) != sorted(s2_norm):
        return False

    # Concatenate and check if it can form a palindrome
    combined = s1_norm + s2_norm
    freq = {}
