def quicksort_optimized(arr):
    if len(arr) <= 1:
        return arr

    pivot = arr[len(arr) // 2]

    # Three-way partitioning to handle duplicates efficiently
    less = []
    equal = []
    greater = []

    for x in arr:
        if x < pivot:
            less.append(x)
        elif x > pivot:
