def fibonacci(n):
    """
    Compute the nth Fibonacci number using memoization to avoid redundant calculations.
    F(0) = 0, F(1) = 1, F(n) = F(n-1) + F(n-2) for n >= 2.
    """
    memo = {0: 0, 1: 1}

    def helper(k):
        if k in memo:
            return memo[k]
        memo[k] = helper(k - 1) + helper(k - 2)
        return memo[k]

    return helper(n)
