```python
def circularSearch(nums, target):
    n = len(nums)
    if n == 0:
        return False

    # Find the pivot point where the array wraps around
    # In a sorted circular array, the pivot is the index where nums[i] > nums[i+1]
    left, right = 0, n - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            # Pivot is in the left half (including mid)
            left = mid + 1
        else:
            # Pivot is in the right half
            right = mid

    pivot = left  # Start of the sorted portion (smallest element)

    # Now perform binary search on the two sorted segments:
    # Segment 1: [pivot, n-1]
    # Segment 2: [0, pivot-1]

    # Search in Segment 1
    l, r = pivot, n - 1
    while l <= r:
        mid = (l + r) // 2
        if nums[mid] == target:
            return True
        elif nums[mid] < target:
            l = mid + 1
        else:
            r = mid - 1

    # Search in Segment 2
    l, r = 0, pivot - 1
    while l <= r:
        mid = (l + r) // 2
        if nums[mid] == target:
            return True
        elif nums[mid] < target:
            l = mid + 1
        else:
            r = mid - 1

    return False
