def construct_tree(pre_order):
    if not pre_order:
        return None

    index = [0]  # Use a list to allow modification inside nested function

    def build(lower, upper):
        if index[0] == len(pre_order):
            return None
        val = pre_order[index[0]]
        if val < lower or val > upper:
            return None
        index[0] += 1
        node = TreeNode(val)
        node.left = build(lower, val - 1)
        node.right = build(val + 1, upper)
        return node

