def longest_common_subsequence(s1: str, s2: str) -> int:
    m, n = len(s1), len(s2)
    # Use a single array of size n+1 to store the current row of DP
    dp = [0] * (n + 1)

    for i in range(1, m + 1):
        prev = 0  # Represents dp[i-1][j-1]
        for j in range(1, n + 1):
            temp = dp[j]  # Store dp[i-1][j] before overwriting
            if s1[i - 1] == s2[j - 1]:
                dp[j] = prev + 1
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = temp  # Update prev for next iteration (becomes dp[i-1][j])

    return dp[n]
