        14: "fourteen", 15: "fifteen", 16: "sixteen", 17: "seventeen",
        18: "eighteen", 19: "nineteen"
    }

    tens = {
        2: "twenty", 3: "thirty", 4: "forty", 5: "fifty",
        6: "sixty", 7: "seventy", 8: "eighty", 9: "ninety"
    }

    def number_to_words(n):
        if n < 20:
            return ones[n]
        elif n < 100:
            tens_digit = n // 10
            ones_digit = n % 10
            if ones_digit == 0:
                return tens[tens_digit]
            else:
                return f"{tens[tens_digit]} {ones[ones_digit]}"
        else:
            # This part should not be reached for HH, MM, SS in valid time
            return "invalid"

    # Parse HH:MM:SS
    hh, mm, ss = map(int, time_str.split(':'))

    # Convert each part to words
    h_words = number_to_words(hh)
    m_words = number_to_words(mm)
    s_words = number_to_words(ss)

    return f"{h_words} hours {m_words} minutes {s_words} seconds"
