def find_most_common_pixel_value(image):
    if not image or not image[0]:
        return None

    top_row = image[0]
    bottom_row = image[-1]

    # Find intersection of values present in both top and bottom rows
    common_values = set(top_row) & set(bottom_row)

    if not common_values:
        return None

    # Count frequencies of common values in the entire image
    from collections import Counter
    counter = Counter()
    for row in image:
        for val in row:
            if val in common_values:
                counter[val] += 1

    # Return the value with the highest frequency
    return max(counter, key=counter.get)
