def quicksort(arr):
    def median_of_three(left, mid, right):
        a, b, c = arr[left], arr[mid], arr[right]
        if a <= b <= c or c <= b <= a:
            return b
        elif b <= a <= c or c <= a <= b:
            return a
        else:
            return c

    def partition(low, high):
        if high - low < 2:
            # If less than 3 elements, just pick the last as pivot
            pivot = arr[high]
        else:
            mid = (low + high) // 2
            pivot = median_of_three(low, mid, high)
            # Find the index of the pivot value to swap into high
            for i in range(low, high + 1):
                if arr[i] == pivot:
                    arr[i], arr[high] = arr[high], arr[i]
                    break

        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    def quicksort_recursive(low, high):
        if low < high:
            pi = partition(low, high)
            quicksort_recursive(low, pi - 1)
            quicksort_recursive(pi + 1, high)

    if len(arr) <= 1:
        return arr

    quicksort_recursive(0, len(arr) - 1)
    return arr
```

