        if k < 2:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        i = 3
        while i * i <= k:
            if k % i == 0:
                return False
            i += 2
        return True

    n = len(target_str)
    if n != len(rand_str):
        raise ValueError("Strings must be of equal length")

