def custom_sort_words(words):
    # Count frequencies manually
    freq = {}
    for w in words:
        if w in freq:
            freq[w] += 1
        else:
            freq[w] = 1

    # Build list of (word, frequency)
    items = []
    for w in words:
        items.append((w, freq[w]))

    # Implement a simple selection sort based on the custom criteria:
    # 1. Higher frequency first
    # 2. If frequencies equal, alphabetically smaller word first
    n = len(items)
    for i in range(n - 1):
        # Assume current position i has the best element
        best_idx = i
        for j in range(i + 1, n):
            w1, f1 = items[best_idx]
            w2, f2 = items[j]
            # Compare by frequency descending, then by word ascending
            if f2 > f1:
                best_idx = j
            elif f2 == f1:
                if w2 < w1:
                    best_idx = j

        # Swap
        items[i], items[best_idx] = items[best_idx], items[i]

    # Extract sorted words
    result = [item[0] for item in items]
    return result
