def fibonacci(n):
    if not isinstance(n, int):
        return "Input should be a non-negative integer."
    if n < 0:
        return "Input should be a non-negative integer."

    memo = {}

    def fib_memo(k):
        if k in memo:
            return memo[k]
        if k == 0:
            memo[k] = 0
        elif k == 1:
            memo[k] = 1
        else:
            memo[k] = fib_memo(k - 1) + fib_memo(k - 2)
        return memo[k]

