import math

def safe_log(n, base):
    golden_ratio = 1.61803398875

    # Check for non-positive n
    if n <= 0:
        return 0.0

    # Check for non-positive or equal to 1 base
    if base <= 1:
        return 0.0

    # Helper to check if a number is prime (for positive integers)
    def is_prime(x):
        if x <= 1:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    # Adjust base if it is a prime number
    if is_prime(base):
        base = base * golden_ratio

    # Compute and return the logarithm
    return math.log(n, base)
