def max_abs_diff_divide_and_conquer(array):
    def flatten_and_split(arr):
        # Flatten the multi-dimensional array into a 1D list
        flat = []
        for item in arr:
            if isinstance(item, list):
                flat.extend(flatten_and_split(item))
            else:
                flat.append(item)
        return flat

    def find_min_max(arr):
        if not arr:
            return None, None
        if len(arr) == 1:
            return arr[0], arr[0]
        mid = len(arr) // 2
        left_min, left_max = find_min_max(arr[:mid])
        right_min, right_max = find_min_max(arr[mid:])
        return min(left_min, right_min), max(left_max, right_max)

    def compute_max_diff(arr):
        if not arr:
            return 0
        if len(arr) == 1:
            return 0
        # Divide
        mid = len(arr) // 2
        left_diff = compute_max_diff(arr[:mid])
        right_diff = compute_max_diff(arr[mid:])
        # Conquer: find global min and max
        _, global_min = find_min_max(arr)
        _, global_max = find_min_max(arr)
        # The maximum absolute difference is between global min and global max
        return max(left_diff, right_diff, global_max - global_min)

    flat_array = flatten_and_split(array)
    return compute_max_diff(flat_array)
```

