def _escape_html(obj):
    """
    Recursively escape HTML special characters in strings within dictionaries, lists, or nested structures.

    Escapes:
        <  -> &lt;
        >  -> &gt;
        "  -> &quot;
        '  -> &apos;
        &  -> &amp;

    Non-string, non-collection types are returned as-is.
    """
    # Define the mapping of characters to their HTML entities
    escape_map = {
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": "&apos;",
        '&': '&amp;'
    }

    def escape_string(s):
        if not isinstance(s, str):
            return s
        result = []
        for char in s:
            if char in escape_map:
                result.append(escape_map[char])
            else:
                result.append(char)
        return ''.join(result)

    if isinstance(obj, str):
        return escape_string(obj)
    elif isinstance(obj, dict):
        return {
            key: _escape_html(value) if not isinstance(key, str) else escape_string(key)
            for key, value in obj.items()
        }
    elif isinstance(obj, (list, tuple)):
        return [_escape_html(item) for item in obj]
    else:
        return obj
