def checkInclusion(P, S):
    # Frequency arrays for 26 lowercase and 26 uppercase letters
    # We map 'a'-'z' to 0-25 and 'A'-'Z' to 26-51
    def get_freq_map(s):
        freq = [0] * 52
        for ch in s:
            if 'a' <= ch <= 'z':
                idx = ord(ch) - ord('a')
            else:
                idx = ord(ch) - ord('A') + 26
            freq[idx] += 1
        return freq

    def arrays_equal(a, b):
        for i in range(52):
            if a[i] != b[i]:
                return False
        return True

    p_len = len(P)
    s_len = len(S)

    if p_len > s_len:
        return False

    p_freq = get_freq_map(P)
    s_window_freq = get_freq_map(S[:p_len])

    if arrays_equal(p_freq, s_window_freq):
        return True

    # Slide the window over S
    for i in range(p_len, s_len):
        # Add new character
        new_char = S[i]
        if 'a' <= new_char <= 'z':
            idx = ord(new_char) - ord('a')
        else:
            idx = ord(new_char) - ord('A') + 26
        s_window_freq[idx] += 1

        # Remove old character
        old_char = S[i - p_len]
        if 'a' <= old_char <= 'z':
            idx_old = ord(old_char) - ord('a')
        else:
            idx_old = ord(old_char) - ord('A') + 26
        s_window_freq[idx_old] -= 1

        if arrays_equal(p_freq, s_window_freq):
            return True

    return False
```

