    # Check if input looks like a file path (contains path separators or is not valid JSON)
    # We attempt to parse it as JSON first; if it fails and contains path-like characters, treat as file
    try:
        json.loads(input_source)
        json_str = input_source
    except json.JSONDecodeError:
        # Assume it's a file path
        try:
            with open(input_source, 'r', encoding='utf-8') as f:
                json_str = f.read()
