def is_equable_triangle(a, b, c):
    # Check if sides form a valid triangle
    if a + b <= c or a + c <= b or b + c <= a:
        return False

    # Check if all sides are prime numbers
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    if not (is_prime(a) and is_prime(b) and is_prime(c)):
        return False

    # Check if scalene (all sides different)
    if a == b or b == c or a == c:
        return False

    # Calculate perimeter
    perimeter = a + b + c

    # Calculate area using Heron's formula
    s = perimeter / 2
    area = (s * (s - a) * (s - b) * (s - c)) ** 0.5

    # Check if area equals perimeter (allowing for floating point tolerance)
    if abs(area - perimeter) < 1e-9:
        return True

    return False
