def convert_temperature(temperature, initial_unit, final_unit):
    # Validate input types
    if not isinstance(temperature, (int, float)):
        return None
    if not isinstance(initial_unit, str) or not isinstance(final_unit, str):
        return None

    # Normalize unit names
    initial_unit = initial_unit.strip().capitalize()
    final_unit = final_unit.strip().capitalize()

    valid_units = {'Celsius', 'Fahrenheit', 'Kelvin'}
    if initial_unit not in valid_units or final_unit not in valid_units:
        return None

    # Convert everything to Celsius first, then to the target unit
    def to_celsius(temp, unit):
        if unit == 'Celsius':
            return temp
        elif unit == 'Fahrenheit':
            return (temp - 32) * 5 / 9
        elif unit == 'Kelvin':
            return temp - 273.15
        return None

    def from_celsius(celsius, unit):
        if unit == 'Celsius':
            return celsius
        elif unit == 'Fahrenheit':
            return celsius * 9 / 5 + 32
        elif unit == 'Kelvin':
            return celsius + 273.15
        return None

    celsius_temp = to_celsius(temperature, initial_unit)
    if celsius_temp is None:
        return None

    result = from_celsius(celsius_temp, final_unit)
    if result is None:
        return None

    return float(result)
