        raise ValueError("n must be a positive integer")
    if n == 1:
        return 1
    if n == 2:
        return 1  # f(2) = f(1) + f(0); but f(0) is not defined, so we infer from sequence: 1,1,2,3,5...

    # Using iterative approach to avoid recursion depth issues and improve performance
