def generate_prime_factors(n):
    if n <= 1:
        return []

    factors = []
    # Handle factor 2 separately
    if n % 2 == 0:
        factors.append(2)
        while n % 2 == 0:
            n //= 2

    # Check odd factors from 3 upwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            factors.append(i)
            while n % i == 0:
                n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        factors.append(n)

    return factors
