def find_insertion_index_and_count(numbers, target):
    # Find the first index where target could be inserted to maintain order
    # This is equivalent to finding the leftmost index where numbers[i] >= target
    left, right = 0, len(numbers)
    while left < right:
        mid = (left + right) // 2
        if numbers[mid] < target:
            left = mid + 1
        else:
            right = mid
    index = left

    # Count occurrences of target in the list
    count = 0
    for num in numbers:
        if num == target:
            count += 1
        elif num > target:
            break

    return (index, count)
