from typing import List

def paragraph_tokenize(text: str, engine: str) -> List[str]:
    if not isinstance(text, str):
        return []

    if not text:
        return []

    if engine == "double_newline":
        paragraphs = text.split("\n\n")
    elif engine == "tab_indentation":
        # Split on newline, then treat lines starting with tab as new paragraphs
        lines = text.split("\n")
        paragraphs = []
        current_para = []
        for line in lines:
            if line.startswith("\t"):
                if current_para:
                    paragraphs.append(" ".join(current_para))
                    current_para = []
            current_para.append(line)
        if current_para:
            paragraphs.append(" ".join(current_para))
    else:
        return []

    # Trim leading/trailing spaces from each paragraph and filter out empty ones
    result = [p.strip() for p in paragraphs if p.strip()]
    return result
