```python
def get_complex_quadrant(z):
    """
    Determine the quadrant or axis of a complex number z.

    Numbers within 1e-9 of the real or imaginary axis are considered to lie on the axis.

    Returns:
        str: One of:
            "First quadrant", "Second quadrant", "Third quadrant", "Fourth quadrant",
            "X-axis positive", "X-axis negative", "X-axis origin",
            "Y-axis positive", "Y-axis negative", "Y-axis origin",
            "Origin"
    """
    x = z.real
    y = z.imag
    eps = 1e-9

    # Check if on axes
    on_x_axis = abs(y) <= eps
    on_y_axis = abs(x) <= eps

    if on_x_axis and on_y_axis:
        return "Origin"

    if on_x_axis:
        if y > eps:
            return "Y-axis positive"
        elif y < -eps:
            return "Y-axis negative"
        else:
            return "Y-axis origin"

    if on_y_axis:
        if x > eps:
            return "X-axis positive"
        elif x < -eps:
            return "X-axis negative"
        else:
            return "X-axis origin"

    # Determine quadrant
    if x > eps and y > eps:
        return "First quadrant"
    elif x < -eps and y > eps:
        return "Second quadrant"
    elif x < -eps and y < -eps:
        return "Third quadrant"
    elif x > eps and y < -eps:
        return "Fourth quadrant"
    else:
        # Fallback for edge cases that slipped through
        if abs(x) <= eps or abs(y) <= eps:
            return "Origin"
        return "Unknown"
```

