def find_largest_prime_below(n):
    if n <= 2:
        return None

    # Sieve of Eratosthenes up to n-1
    limit = n - 1
    is_prime = bytearray([1]) * (limit + 1)
    is_prime[0] = 0
    is_prime[1] = 0

    import math
    for i in range(2, int(math.isqrt(limit)) + 1):
        if is_prime[i]:
            step_start = i * i
            is_prime[step_start:limit+1:i] = bytearray([0]) * ((limit - step_start) // i + 1)

    # Scan from limit downwards to find the first prime
    for num in range(limit, 1, -1):
        if is_prime[num]:
            return num

    return None
