def search_sorted_grid(grid, target):
    if not grid or not grid[0]:
        return (-1, -1)

    rows = len(grid)
    cols = len(grid[0])

    # Start from top-right corner
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        val = grid[row][col]
        if val == target:
            return (row, col)
        elif val < target:
            # Move down because current row's max is too small
            row += 1
        else:
            # Move left because current column's max is too large
            col -= 1

    return (-1, -1)
