def longest_prime_subarray(arr):
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    n = len(arr)
    if n == 0:
        return (-1, -1, [])

    best_start = -1
    best_end = -1
    best_sub = []

    current_start = -1

    for i in range(n):
        if is_prime(arr[i]):
            if current_start == -1:
                current_start = i
            current_end = i
        else:
            if current_start != -1:
                length = current_end - current_start + 1
                if length > len(best_sub):
                    best_start = current_start
                    best_end = current_end
                    best_sub = arr[current_start:current_end + 1]
                current_start = -1

    # Check if the last segment is still active
    if current_start != -1:
        length = n - current_start
        if length > len(best_sub):
            best_start = current_start
            best_end = n - 1
            best_sub = arr[current_start:]

    if best_start == -1:
        return (-1, -1, [])

    return (best_start, best_end, best_sub)
