import re

def validate_data_type(data_type_str):
    if not isinstance(data_type_str, str):
        return False

    s = data_type_str.strip()
    if not s:
        return False

    # Normalize to uppercase for comparison
    s_upper = s.upper()

    # Define valid base types
    base_types = ['VARCHAR', 'DECIMAL', 'BOOLEAN', 'BIGINT', 'CHAR', 'TEXT', 'DATE', 'TIMESTAMP']

    # Check for exact match (no parentheses)
    if s_upper in base_types:
        return True

    # Check for types with parameters (must end with parentheses)
    if not s_upper.endswith(')'):
        return False

    # Extract the part inside parentheses
    match = re.match(r'^([A-Z]+)\((.*)\)$', s_upper)
    if not match:
        return False

    type_name = match.group(1)
    params_str = match.group(2)

    if type_name == 'VARCHAR':
        if not params_str.isdigit() or params_str == '':
            return False
        return True

    if type_name == 'CHAR':
        if not params_str.isdigit() or params_str == '':
            return False
        return True

    if type_name == 'DECIMAL':
        parts = params_str.split(',')
        if len(parts) != 2:
            return False
        m_str, n_str = parts
        if not m_str.isdigit() or not n_str.isdigit() or m_str == '' or n_str == '':
            return False
        m = int(m_str)
        n = int(n_str)
        if m <= 0 or n <= 0:
            return False
        if n > m:
            return False
        return True

    # No other parameterized types are allowed
    return False
```

