        if x < 2:
            return None
        for i in range(x, 1, -1):
            if i > 2 and i % 2 == 0:
                continue
            is_prime = True
            for d in range(2, int(math.isqrt(i)) + 1):
                if i % d == 0:
                    is_prime = False
                    break
            if i == 2 or is_prime:
                return i
        return 2  # fallback, though loop should catch 2

    def find_smallest_prime_geq(x):
