                continue
            is_prime = True
            for d in range(2, int(math.isqrt(i)) + 1):
                if i % d == 0:
                    is_prime = False
                    break
            if is_prime:
                return i
        return 2

    largest_prime = find_largest_prime_leq(num_sides)
    smallest_prime = find_smallest_prime_geq(largest_prime)

