def find_primes_in_range(start, end):
    if end < 2:
        return []

    # Sieve of Eratosthenes up to end
    is_prime = [True] * (end + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(end ** 0.5) + 1):
        if is_prime[i]:
            for multiple in range(i * i, end + 1, i):
