import random

def find_kth_smallest(arr, k):
    """
    Find the k-th smallest element in an unsorted list using Quickselect.
    k is 1-based.
    """
    if not arr or k < 1 or k > len(arr):
        raise ValueError("Invalid k or empty array")

    def quickselect(left, right, target_k):
        if left == right:
            return arr[left]

        # Random pivot to avoid worst-case on sorted inputs
        pivot_index = random.randint(left, right)
        pivot_value = arr[pivot_index]

        # Partition: elements < pivot on left, > pivot on right, equal in middle
        store_index = left
        for i in range(left, right):
            if arr[i] < pivot_value:
                arr[store_index], arr[i] = arr[i], arr[store_index]
                store_index += 1

        # Place pivot in correct position
        pivot_index = store_index
        arr[pivot_index], arr[pivot_index] = arr[pivot_index], arr[pivot_index]

        # Count elements equal to pivot
        equal_count = 0
        for i in range(left, right + 1):
            if arr[i] == pivot_value:
                equal_count += 1

        # Determine which partition contains the k-th element
        if k <= store_index - left + 1:
            # k-th is in the left partition (including pivot)
            return quickselect(left, store_index - 1, k)
        elif k <= store_index - left + 1 + equal_count:
            # k-th is one of the equal elements (pivot)
            return pivot_value
        else:
            # k-th is in the right partition
            return quickselect(store_index + 1, right, k - (store_index - left + 1 + equal_count))

    return quickselect(0, len(arr) - 1, k)
```

