def validate_username(username):
    # Check for invalid characters first (anything not alphanumeric or underscore)
    # We ignore whitespace for character validation as per rule 4, but any other invalid char fails.
    cleaned_for_char_check = username.replace(" ", "")
    for ch in cleaned_for_char_check:
        if not (ch.isalnum() or ch == '_'):
            return "username can only contain alphanumeric characters and underscores"

    # Remove all whitespace for length and logic checks
    no_whitespace = username.replace(" ", "")

    # Rule 2: at least 3 characters when whitespace is ignored
    if len(no_whitespace) < 3:
        return "username must be at least 3 characters long"

    # Rule 3: at least 3 letters before any number or underscore
    letter_count_before_special = 0
    for ch in no_whitespace:
        if ch.isdigit() or ch == '_':
            break
        if ch.isalpha():
            letter_count_before_special += 1

    if letter_count_before_special < 3:
        return "username must have at least 3 letters before any number or underscore"

    return "valid"
