def most_common_values(dict_list: List[Dict[str, int]]) -> Dict[str, int]:
    if not dict_list:
        return {}

    # Collect all values for each key across all dictionaries
    key_values: Dict[str, List[int]] = {}
    for d in dict_list:
        for k, v in d.items():
            if k not in key_values:
                key_values[k] = []
            key_values[k].append(v)

