def nearest_prime(number):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if number <= 3:
        return 2 if number == 1 else 2  # 1 -> 2, 2 -> 2, 3 -> 3
    if number == 2:
        return 2
    if number == 3:
        return 3

    start = number if number % 6 in (1, 5) else number + (6 - number % 6) % 6
    if start < 2:
        start = 2

    while True:
        if is_prime(start):
            return start
        start += 6
        if start % 6 == 1:
            # Check the 5 mod 6 candidate before moving to next 1 mod 6
            if is_prime(start - 4):
                return start - 4
        # Check the 5 mod 6 candidate
        if is_prime(start - 4):
            return start - 4
        # Move to next 1 mod 6 candidate
        start += 2
        if is_prime(start):
            return start
