def prettyPrint(v):
    # Handle zero explicitly
    if v == 0:
        return "0"

    abs_v = abs(v)

    # Check if v is effectively an integer (within floating point tolerance)
    # and its absolute value is less than 1000
    if abs_v < 1000 and v == int(v):
        return str(int(v))

    # Determine magnitude-based formatting
    if abs_v >= 1000 or abs_v <= 0.001:
        return f"{v:.1e}"
    elif abs_v < 0.01:
        return f"{v:.4f}"
    elif abs_v < 0.1:
        return f"{v:.3f}"
    elif abs_v < 1:
        return f"{v:.2f}"
    elif abs_v < 10:
        return f"{v:.1f}"
    elif abs_v < 100:
        return f"{v:.1f}"
    else:
        # abs_v >= 100 and not already handled as integer < 1000
        # Return as integer if it's effectively an integer
        if v == int(v):
            return str(int(v))
        else:
            return f"{v:.1f}"
