import re
import json

def extract_json_data_from_html(html_content):
    # Find the last <script> tag before </body>
    # We look for the pattern of a script tag that contains "root.App.main ="
    # and is located before the closing </body> tag.

    # Split the content to find the part before </body>
    body_end_index = html_content.rfind('</body>')
    if body_end_index == -1:
        return {}

    content_before_body = html_content[:body_end_index]

    # Find all script tags in the content before </body>
    script_pattern = r'<script[^>]*>(.*?)</script>'
    matches = list(re.finditer(script_pattern, content_before_body, re.DOTALL))

    if not matches:
        return {}

    # Get the last script tag
    last_script_match = matches[-1]
    script_content = last_script_match.group(1)

    # Look for the assignment to root.App.main
    # Pattern: root.App.main = <JSON>;
    assignment_pattern = r'root\.App\.main\s*=\s*(\{.*?\});'
    assignment_match = re.search(assignment_pattern, script_content, re.DOTALL)

    if not assignment_match:
        return {}

    json_str = assignment_match.group(1)

    try:
        # Parse the JSON string
        json_data = json.loads(json_str)
        return json_data
    except json.JSONDecodeError:
        return {}
