def infix_to_postfix(expression):
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        '^': 3
    }

    right_assoc = {'^'}

    output = []
    stack = []

    tokens = expression.split()

    for token in tokens:
        if token.isdigit() or (token.startswith('-') and len(token) > 1 and token[1:].isdigit()):
            output.append(token)
        elif token in precedence:
            while (stack and stack[-1] in precedence and
                   ((token not in right_assoc and precedence[stack[-1]] >= precedence[token]) or
                    (token in right_assoc and precedence[stack[-1]] > precedence[token]))):
                output.append(stack.pop())
            stack.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            if stack and stack[-1] == '(':
                stack.pop()
            else:
                raise ValueError("Mismatched parentheses")
        else:
            raise ValueError(f"Invalid token: {token}")

    while stack:
        top = stack.pop()
        if top in ('(', ')'):
            raise ValueError("Mismatched parentheses")
        output.append(top)

    return ' '.join(output)
```

