def prime_factor_exponent(num):
    if num <= 1:
        return {}

    factors = {}
    divisor = 2

    # Handle factor 2 separately to allow skipping even numbers later
    while num % divisor == 0:
        factors[divisor] = factors.get(divisor, 0) + 1
        num //= divisor

    divisor = 3
    # Check only up to sqrt(num)
    while divisor * divisor <= num:
        while num % divisor == 0:
            factors[divisor] = factors.get(divisor, 0) + 1
            num //= divisor
        divisor += 2  # Skip even numbers

    # If num is still greater than 1, then it's a prime factor
    if num > 1:
        factors[num] = factors.get(num, 0) + 1

    return factors
