def min_initial_array_size(A):
    import math

    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        r = int(math.isqrt(x))
        for i in range(3, r + 1, 2):
            if x % i == 0:
                return False
        return True

    def prime_factors(x):
        factors = []
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors.append(d)
                x //= d
            d += 1
        if x > 1:
            factors.append(x)
        return factors

    # Count total prime factors across all numbers
    total_prime_factors = 0
    for val in A:
        total_prime_factors += len(prime_factors(val))

    # Each initial element can be a distinct prime.
    # We can copy-paste to generate multiples, but each distinct prime
    # must come from the initial array at least once.
    # The minimal size is the number of distinct primes needed to form all numbers.
    # Since we can only use each initial segment once, we cannot reuse a prime
    # to form multiple different prime factors in different numbers unless
    # we have multiple copies in the initial array.
    # Therefore, the answer is the total count of prime factors (with multiplicity).

    return total_prime_factors
