import numpy as np

def spiralOrder(grid):
    if not isinstance(grid, np.ndarray):
        grid = np.array(grid)

    m, n = grid.shape
    if m == 0 or n == 0:
        return []

    result = []
    top, bottom = 0, m - 1
    left, right = 0, n - 1

    while top <= bottom and left <= right:
        # Traverse right along the top row
        for col in range(left, right + 1):
            result.append((top, col, int(grid[top, col])))
        top += 1

        # Traverse down along the right column
        for row in range(top, bottom + 1):
            result.append((row, right, int(grid[row, right])))
        right -= 1

        # Traverse left along the bottom row (if there's still a row)
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append((bottom, col, int(grid[bottom, col])))
            bottom -= 1

        # Traverse up along the left column (if there's still a column)
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append((row, left, int(grid[row, left])))
            left += 1

    return result
