def normalize_dataset(dataset):
    if not dataset:
        return []

    num_rows = len(dataset)
    num_cols = len(dataset[0])
    normalized = [[None for _ in range(num_cols)] for _ in range(num_rows)]

    for col in range(num_cols):
        values = [row[col] for row in dataset if row[col] is not None]
        if not values:
            continue  # All None in this column; leave normalized as None

        min_val = min(values)
        max_val = max(values)

        if min_val == max_val:
            # All same value -> normalized to 0.0
            for row in range(num_rows):
                if dataset[row][col] is not None:
                    normalized[row][col] = 0.0
        else:
            for row in range(num_rows):
                val = dataset[row][col]
                if val is not None:
                    normalized[row][col] = (val - min_val) / (max_val - min_val)
                else:
                    normalized[row][col] = None

    return normalized
