def find_infected_computers(networks):
    """
    networks: list of tuples
      Each tuple: (initial_infected_id, num_packets, list_of_packets)
      list_of_packets: list of (sender, destination) tuples

    Returns:
      list of strings, each string contains space-separated sorted infected computer IDs
      for the corresponding network.
    """
    results = []

    for initial_id, num_packets, packets in networks:
        infected = {initial_id}
        changed = True

        # Build adjacency list for the current network
        adj = {}
        for s, d in packets:
            if s not in adj:
                adj[s] = []
            adj[s].append(d)

        # BFS/queue-based propagation
        queue = [initial_id]
        visited = {initial_id}

        import collections
        q = collections.deque([initial_id])

        while q:
            node = q.popleft()
            if node in adj:
                for neighbor in adj[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        q.append(neighbor)

        sorted_infected = sorted(visited)
        results.append(" ".join(map(str, sorted_infected)))

    return results
