def create_full_name(first_name, last_name, middle_name=None, titles=None, suffixes=None):
    # Normalize name components: capitalize first letter, lowercase the rest
    def normalize(name):
        if not name:
            return ""
        return name[0].upper() + name[1:].lower() if len(name) > 1 else name.upper()

    # Normalize titles and suffixes
    if titles:
        titles = [normalize(t) for t in titles]
    else:
        titles = []

    if suffixes:
        suffixes = [normalize(s) for s in suffixes]
    else:
        suffixes = []

    # Build the name part
    name_parts = [normalize(first_name), normalize(last_name)]
    if middle_name:
        name_parts.insert(1, normalize(middle_name))

    # Build the full string
    result_parts = []
    result_parts.extend(titles)
    result_parts.append(", ".join(name_parts))
    result_parts.extend(suffixes)

    return ", ".join(result_parts)
