def parse_query_string(query_string):
    from urllib.parse import unquote_plus

    result = {}

    if not query_string:
        return result

    # Split by '&' to get individual key-value pairs
    pairs = query_string.split('&')

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            # Handle keys without values (e.g., "flag")
            key = pair
            value = ''

        # Decode URL-encoded characters
        decoded_key = unquote_plus(key)
        decoded_value = unquote_plus(value)

        if decoded_key in result:
            # If key already exists, convert to list and append
            if not isinstance(result[decoded_key], list):
                result[decoded_key] = [result[decoded_key]]
            result[decoded_key].append(decoded_value)
        else:
            result[decoded_key] = decoded_value

    return result
