def find_target_in_array2d(array2d, target):
    """
    Find all occurrences of `target` in a 2D array and return their (row, column) indices.

    Parameters:
        array2d (list): A 2D list where each element is either a string or a number.
        target: The value to search for (string or number).

    Returns:
        list: A list of tuples (row, column) where `target` was found.
              Returns an empty list if not found or if the array is empty.
    """
    result = []
    if not array2d:
        return result

    for row_idx, row in enumerate(array2d):
        if not isinstance(row, list):
            continue  # Skip non-list rows if any
        for col_idx, value in enumerate(row):
            if value is target:
                result.append((row_idx, col_idx))
            elif isinstance(value, (int, float)) and isinstance(target, (int, float)):
                if value == target:
                    result.append((row_idx, col_idx))
            elif isinstance(value, str) and isinstance(target, str):
                if value == target:
                    result.append((row_idx, col_idx))

    return result
```

