def count_prime_factors(N):
    if N <= 1:
        return 0

    count = 0

    # Handle factor 2 separately
    if N % 2 == 0:
        count += 1
        while N % 2 == 0:
            N //= 2

    # Check odd factors from 3 up to sqrt(N)
    f = 3
    while f * f <= N:
        if N % f == 0:
            count += 1
            while N % f == 0:
                N //= f
        f += 2

    # If N is still greater than 1, then it's a prime factor
    if N > 1:
        count += 1

    return count
