def is_primitive(obj):
    # Check for standard primitive types
    if isinstance(obj, (int, float, bool, str)):
        return True

    # Check for None explicitly (it's not a primitive in this definition)
    if obj is None:
        return False

    # Check for custom objects with __primitive__ method
    if hasattr(obj, '__primitive__') and callable(getattr(obj, '__primitive__')):
        return obj.__primitive__()

    # All other types (sequences, mappings, etc.) are not primitives
    return False
