def find_path(root, target):
    if root is None:
        return []

    path = []

    def dfs(node, t):
        if node is None:
            return False

        path.append(node.val)

        if node.val == t:
            return True

        if dfs(node.left, t) or dfs(node.right, t):
            return True

        path.pop()
        return False

    dfs(root, target)
    return path if path else []
