def convert_to_binary(n):
    if n == 0:
        return "0"

    binary_digits = []
    while n > 0:
        remainder = n % 2
        binary_digits.append(str(remainder))
        n //= 2

    # The digits were collected in reverse order
    return ''.join(reversed(binary_digits))
