import statistics

def calculate_central_tendency(data, operation):
    if not isinstance(data, list):
        raise TypeError("Data must be a list.")

    if operation == "mean":
        if len(data) == 0:
            raise ValueError("Cannot calculate mean of an empty dataset.")
        return sum(data) / len(data)

    elif operation == "median":
        if len(data) == 0:
            raise ValueError("Cannot calculate median of an empty dataset.")
        return statistics.median(data)

    elif operation == "mode":
        if len(data) == 0:
            raise ValueError("Cannot calculate mode of an empty dataset.")
        counts = Counter(data)
        max_count = max(counts.values())
        modes = [value for value, count in counts.items() if count == max_count]
        return modes
    else:
        raise AssertionError("Unsupported operation. Please use 'mean', 'median', or 'mode'.")
