def reverse_string(s):
    if not s:
        return ""

    result = []
    for char in s:
        result.append(char)

    # Reverse the list manually
    left = 0
    right = len(result) - 1
    while left < right:
        result[left], result[right] = result[right], result[left]
        left += 1
        right -= 1

    return "".join(result)
