from datetime import datetime, timezone

def http_to_dt(http_date: str) -> datetime:
    # Format 1: "Tue, 15 Nov 1994 12:45:26 GMT"
    fmt1 = "%a, %d %b %Y %H:%M:%S GMT"
    # Format 2: "Sunday, 06-Nov-94 08:49:37 GMT"
    fmt2 = "%A, %d-%b-%y %H:%M:%S GMT"
    # Format 3: "Sun Nov  6 08:49:37 1994"
    fmt3 = "%a %b %d %H:%M:%S %Y"

    try:
        dt = datetime.strptime(http_date, fmt1)
        return dt.replace(tzinfo=timezone.utc)
    except ValueError:
        pass

    try:
        dt = datetime.strptime(http_date, fmt2)
        return dt.replace(tzinfo=timezone.utc)
    except ValueError:
        pass

    try:
        dt = datetime.strptime(http_date, fmt3)
        return dt.replace(tzinfo=timezone.utc)
    except ValueError:
        raise ValueError(f"Unsupported HTTP date format: {http_date}")
