            return True
        # Check mismatch
        if chars[left] != chars[right]:
            return False
        # Recurse inward
        return is_palindrome_chars(chars, left + 1, right - 1)

    # Normalize input string into a list of characters
    normalized = normalize(s)
    # Start recursive check from both ends
    return is_palindrome_chars(normalized, 0, len(normalized) - 1)
