def find_pair_sum(numbers, target, left=None, right=None):
    if left is None:
        left = 0
    if right is None:
        right = len(numbers) - 1

    if left >= right:
        return None

    mid = (left + right) // 2
    current = numbers[mid]
    needed = target - current

    # Binary search for 'needed' in the range [left, mid-1]
    def binary_search(arr, val, l, r):
        while l <= r:
            m = (l + r) // 2
            if arr[m] == val:
                return m
            elif arr[m] < val:
                l = m + 1
            else:
                r = m - 1
        return None

    idx = binary_search(numbers, needed, left, mid - 1)
    if idx is not None:
        return (idx, mid)

    # If not found in left half, search in right half
    return find_pair_sum(numbers, target, mid + 1, right)
