def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping:
            # It's a closing bracket
            if not stack:
                return False
            top = stack.pop()
            if mapping[char] != top:
                return False
        else:
            # It's an opening bracket
            stack.append(char)

    return len(stack) == 0
