def debug_on_error(func):
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception:
            # Find the innermost exception frame
            exc_type, exc_value, exc_tb = sys.exc_info()
            # Walk up the traceback to find the deepest frame that is not in this wrapper
            while exc_tb.tb_next is not None:
                exc_tb = exc_tb.tb_next
                # Stop if we hit a frame inside this wrapper (shouldn't happen normally)
                if exc_tb.tb_frame.f_code.co_name == 'wrapper':
                    break

            # Start pdb at the innermost exception frame
            pdb.post_mortem(exc_tb)
            # Re-raise the exception so it can be handled by outer handlers
            raise

    return wrapper
