        return suffixes.get(d % 10, "th")

    # Validate month
    if month < 1 or month > 12:
        return "Invalid Date"

    # Determine days in month
    if month in (1, 3, 5, 7, 8, 10, 12):
        max_day = 31
    elif month in (4, 6, 9, 11):
        max_day = 30
    elif month == 2:
        if is_leap(year):
            max_day = 29
        else:
            max_day = 28
    else:
        return "Invalid Date"

    # Validate day
    if day < 1 or day > max_day:
        return "Invalid Date"

    # Format day with ordinal suffix and month with zero padding
    day_str = f"{day}{get_ordinal_suffix(day)}"
    month_str = f"{month:02d}"

    return f"{day_str}-{month_str}-{year}"
