import threading

class Group:
    def __init__(self, name, attrs=None):
        self.name = name
        self.attrs = attrs if attrs is not None else {}
        self.subgroups = {}
        self._lock = threading.Lock()

    def to_dict(self):
        return {
            'attrs': self.attrs,
            'subgroups': self.subgroups
        }

class DataManager:
    def __init__(self):
        self._groups = {}
        self._lock = threading.RLock()

    def get_group(self, name):
        with self._lock:
            return self._groups.get(name)

    def create_group(self, name, attrs=None):
        with self._lock:
            if name in self._groups:
                return self._groups[name]
            group = Group(name, attrs)
            self._groups[name] = group
            return group

def create_or_get_group(data_manager, group_name, attrs=None):
    group = data_manager.get_group(group_name)
    if group is None:
        group = data_manager.create_group(group_name, attrs)
    return group.to_dict()
