def class_prefix(*prefixes):
    def decorator(cls):
        # Build the full prefix string
        full_prefix = '_'.join(prefixes)

        # Rename the outer class
        original_name = cls.__name__
        if not original_name.startswith(full_prefix):
            cls.__name__ = f"{full_prefix}_{original_name}"

        # Recursively process nested classes
        for name, value in list(cls.__dict__.items()):
            if isinstance(value, type):
                # It's a nested class
                original_nested_name = value.__name__
                if not original_nested_name.startswith(full_prefix):
                    value.__name__ = f"{full_prefix}_{original_nested_name}"
                # Recurse into the nested class's __dict__
                for nested_name, nested_value in list(value.__dict__.items()):
                    if isinstance(nested_value, type):
                        original_deep_name = nested_value.__name__
                        if not original_deep_name.startswith(full_prefix):
                            nested_value.__name__ = f"{full_prefix}_{original_deep_name}"

        return cls

    return decorator
