class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def generate_tree(preorder, inorder):
    if len(preorder) != len(inorder):
        raise ValueError("preorder and inorder lists must have the same length")
    if len(preorder) == 0:
        return None

    # Build a map from value to index in inorder for quick lookup
    # Since values may not be unique, we store a list of indices for each value
    from collections import defaultdict
    inorder_map = defaultdict(list)
    for idx, val in enumerate(inorder):
        inorder_map[val].append(idx)

    def build(pre_start, pre_end, in_start, in_end):
        if pre_start >= pre_end or in_start >= in_end:
            return None

        root_val = preorder[pre_start]
        root = TreeNode(root_val)

        # Find the first occurrence of root_val in the current inorder range
        # to handle non-unique values correctly
        root_index = None
        for idx in inorder_map[root_val]:
            if in_start <= idx < in_end:
                root_index = idx
                break

        if root_index is None:
            raise ValueError(f"Invalid traversals: root value {root_val} not found in inorder range [{in_start}, {in_end})")

        left_size = root_index - in_start

        root.left = build(pre_start + 1, pre_start + 1 + left_size, in_start, root_index)
        root.right = build(pre_start + 1 + left_size, pre_end, root_index + 1, in_end)

        return root

    return build(0, len(preorder), 0, len(inorder))
```

