def find_duplicates(arr):
    n = len(arr)
    if n < 3:
        return []

    result = []
    # We will count occurrences by scanning multiple times for each candidate
    # Since we cannot use hash sets or dicts, we rely on index-based counting.
    # To avoid modifying the original array, we only read from it.

    # First pass: collect all unique elements in order of first appearance
    # We do this by checking if an element has been seen before using a naive O(n^2) approach
    # which is allowed since no additional data structures are permitted.
    unique_in_order = []
    for i in range(n):
        is_new = True
        for j in range(i):
            if arr[j] == arr[i]:
                is_new = False
                break
        if is_new:
            unique_in_order.append(arr[i])

    # Second pass: count occurrences for each unique element
    for val in unique_in_order:
        count = 0
        for x in arr:
            if x == val:
                count += 1
        if count >= 3:
            result.append(val)

    return result
