def convert_to_hex(n):
    if n == 0:
        return "0"

    # Handle negative numbers as 32-bit two's complement
    if n < 0:
        n = n & 0xFFFFFFFF

    hex_chars = "0123456789abcdef"
    result = []

    while n > 0:
        remainder = n & 0xF
        result.append(hex_chars[remainder])
        n >>= 4

    return ''.join(reversed(result))
