def get_nested_value(data, path):
    if not path:
        return data if isinstance(data, dict) else None

    # Normalize path to lowercase for case-insensitive matching
    path_lower = path.lower()
    current = data

    for key in path_lower.split('.'):
        if not isinstance(current, dict):
            return None

        # Find a key in current that matches the segment case-insensitively
        found = None
        for k in current:
            if k.lower() == key:
                found = k
                break

        if found is None:
            return None

        current = current[found]

