def rec_palindrome(s):
    def clean_index(idx, current_s):
        if idx == len(current_s):
            return -1
        ch = current_s[idx]
        if ch.isalnum():
            return idx
        return clean_index(idx + 1, current_s)

    def check(i, j):
        if i >= j:
            return True
        left = clean_index(i, s)
        right = clean_index(j, s)
        if left == -1 or right == -1:
            return True
        if s[left].lower() != s[right].lower():
            return False
        return check(left + 1, right - 1)

    return check(0, len(s) - 1)
